import { Redirect, Stack, usePathname } from "expo-router";

import { LoadingScreen } from "@/ui/loading-screen";

import { useSession } from "./session-context";

/**
 * The `(app)` group's layout: waits for the persisted session to resolve,
 * sends a signed-out learner to `/sign-in`, and otherwise renders the
 * signed-in stack. The path they were trying to reach — e.g. a deck an
 * email link pointed at — rides along as a `redirect` param, so `/sign-in`
 * can send them there once they're signed in instead of always to the deck
 * list.
 */
export function AuthenticatedLayout() {
  const { session, status } = useSession();
  const pathname = usePathname();

  if (status === "loading") {
    return <LoadingScreen />;
  }

  if (session === null) {
    return (
      <Redirect href={{ pathname: "/sign-in", params: { redirect: pathname } }} />
    );
  }

  return <Stack screenOptions={{ headerShown: false }} />;
}

